namespace drum {
juce::String builtinName(BuiltinKind k){static const char* names[]={"EQ","Compressor","Transient","Saturation","Clipper","Limiter","Gate","Utility","Stereo Width","Dynamic EQ","Bitcrusher","Delay","Ducker","Room","Resonator","Frequency Shifter","Echo"};return names[(int)k];}
juce::PluginDescription builtinDescription(BuiltinKind k){juce::PluginDescription d;d.name="Drum "+builtinName(k);d.manufacturerName="DJ Leslieson";d.pluginFormatName="Drum Built-in";d.fileOrIdentifier="drum:effect:"+juce::String((int)k);d.version="1";d.numInputChannels=k==BuiltinKind::ducker?4:2;d.numOutputChannels=2;d.uniqueId=0x444a1000+(int)k;return d;}
bool isBuiltin(const juce::PluginDescription& d){for(int n=0;n<builtinCount;++n)if(d.pluginFormatName=="Drum Built-in" && d.fileOrIdentifier==builtinDescription((BuiltinKind)n).fileOrIdentifier)return true;return false;}
std::unique_ptr<juce::AudioProcessor> createBuiltin(const juce::PluginDescription& d){if(!isBuiltin(d))return {};return std::make_unique<BuiltinEffect>((BuiltinKind)d.fileOrIdentifier.getTrailingIntValue());}
void BuiltinEffect::parameter(const juce::String& name,float lo,float hi,float value,const juce::String& unit){auto* p=new juce::AudioParameterFloat(juce::ParameterID{"p"+juce::String(controls.size()),1},name,juce::NormalisableRange<float>{lo,hi},value,juce::AudioParameterFloatAttributes{}.withLabel(unit));addParameter(p);controls.push_back(p);}
BuiltinEffect::BuiltinEffect(BuiltinKind k):AudioProcessor([k]{auto buses=BusesProperties().withInput("Input",juce::AudioChannelSet::stereo(),true).withOutput("Output",juce::AudioChannelSet::stereo(),true);if(k==BuiltinKind::ducker)buses=buses.withInput("Sidechain",juce::AudioChannelSet::stereo(),false);return buses;}()),kind(k){
    switch(kind){
    case BuiltinKind::eq:{spectrum=std::make_unique<SpectrumTap>();Equalizer e;parameter("EQ on",0,1,1);parameter("Output",-24,24,0,"dB");for(int n=0;n<16;++n){auto prefix="Band "+juce::String(n+1)+" ";parameter(prefix+"on",0,1,0);parameter(prefix+"type",0,7,(float)e.bands[n].type);parameter(prefix+"frequency",20,20000,(float)e.bands[n].frequency,"Hz");parameter(prefix+"gain",-60,24,0,"dB");parameter(prefix+"Q",.1f,18,.70710678f);}for(int n=0;n<16;++n)parameter("Band "+juce::String(n+1)+" slope",0,72,0,"dB/oct");break;}
    case BuiltinKind::compressor:parameter("Threshold",-60,0,-18,"dB");parameter("Ratio",1,20,4,":1");parameter("Attack",.1f,100,10,"ms");parameter("Release",5,1000,100,"ms");parameter("Makeup",-24,24,0,"dB");parameter("Mix",0,100,100,"%");parameter("Knee",0,24,6,"dB");parameter("SC low cut",0,1000,0,"Hz");break;
    case BuiltinKind::transient:parameter("Attack",-18,18,0,"dB");parameter("Sustain",-18,18,0,"dB");parameter("Length",10,500,100,"ms");parameter("Output",-24,24,0,"dB");break;
    case BuiltinKind::saturation:waveform=std::make_unique<SpectrumTap>();parameter("Drive",0,30,6,"dB");parameter("Mix",0,100,100,"%");parameter("Output",-24,12,0,"dB");parameter("Character",0,2,0);break;
    case BuiltinKind::clipper:parameter("Drive",0,30,0,"dB");parameter("Ceiling",-24,0,-1,"dBFS");parameter("Softness",0,100,0,"%");parameter("Output",-24,0,0,"dB");break;
    case BuiltinKind::limiter:parameter("Input",-24,24,0,"dB");parameter("Ceiling",-24,0,-1,"dBFS");parameter("Release",5,1000,80,"ms");break;
    case BuiltinKind::gate:parameter("Threshold",-80,0,-45,"dB");parameter("Range",0,80,60,"dB");parameter("Attack",.1f,50,1,"ms");parameter("Release",5,1000,100,"ms");break;
    case BuiltinKind::stereoWidth:parameter("Delay",0,30,10,"ms");parameter("Delayed side",0,1,1);parameter("Protect bass",0,1,1);parameter("Bass below",20,500,150,"Hz");parameter("Pan",-100,100,0);parameter("Mix",0,100,0,"%");break;
    case BuiltinKind::dynamicEq:spectrum=std::make_unique<SpectrumTap>();parameter("Frequency",20,20000,3000,"Hz");parameter("Q",.1f,18,2);parameter("Threshold",-60,0,-24,"dB");parameter("Range",-24,24,0,"dB");parameter("Attack",.1f,100,5,"ms");parameter("Release",5,1000,100,"ms");parameter("Mix",0,100,100,"%");break;
    case BuiltinKind::bitcrusher:parameter("Bits",2,24,12);parameter("Sample rate",500,48000,12000,"Hz");parameter("Drive",0,24,0,"dB");parameter("Output",-24,0,0,"dB");parameter("Mix",0,100,0,"%");break;
    case BuiltinKind::tempoDelay:parameter("Time",1,2000,250,"ms");parameter("Sync",0,1,0);parameter("Division",0,8,5);parameter("Feedback",0,85,30,"%");parameter("Low cut",20,1000,100,"Hz");parameter("High cut",1000,20000,12000,"Hz");parameter("Ping pong",0,1,0);parameter("Mix",0,100,0,"%");break;
    case BuiltinKind::ducker:parameter("Threshold",-60,0,-24,"dB");parameter("Depth",0,36,12,"dB");parameter("Attack",.1f,100,2,"ms");parameter("Hold",0,250,20,"ms");parameter("Release",5,1000,100,"ms");parameter("Mix",0,100,100,"%");break;
    case BuiltinKind::room:parameter("Predelay",0,100,10,"ms");parameter("Room size",0,1,.35f);parameter("Damping",0,1,.5f);parameter("Low cut",20,1000,150,"Hz");parameter("Mix",0,100,0,"%");break;
    case BuiltinKind::resonator:parameter("Frequency",30,10000,440,"Hz");parameter("Decay",10,2000,250,"ms");parameter("Damping",500,18000,8000,"Hz");parameter("Drive",0,24,0,"dB");parameter("Mix",0,100,0,"%");break;
    case BuiltinKind::frequencyShifter:parameter("Shift",-2000,2000,0,"Hz");parameter("Output",-24,12,0,"dB");parameter("Mix",0,100,0,"%");break;
    case BuiltinKind::echo:parameter("Time",1,2000,250,"ms");parameter("Sync",0,1,0);parameter("Division",0,8,5);parameter("Feedback",0,95,35,"%");parameter("Low cut",20,3000,100,"Hz");parameter("High cut",200,20000,4500,"Hz");parameter("Ping pong",0,1,0);parameter("Mix",0,100,30,"%");parameter("Drive",0,24,6,"dB");parameter("Wow",0,100,10,"%");parameter("Wow rate",.1f,5,.3f,"Hz");break;
    case BuiltinKind::utility:parameter("Gain",-60,24,0,"dB");parameter("Width",0,200,100,"%");parameter("Invert L",0,1,0);parameter("Invert R",0,1,0);parameter("Channels",0,3,0);parameter("Pan",-100,100,0);break;
    }
    smooth.resize(controls.size());
}
Equalizer BuiltinEffect::equalizer() const{Equalizer e;e.enabled=controls[0]->get()>=.5f;e.output=controls[1]->get();for(int n=0;n<16;++n){auto& b=e.bands[n];int i=2+n*5;b.enabled=controls[i]->get()>=.5f;b.type=juce::roundToInt(controls[i+1]->get());b.frequency=controls[i+2]->get();b.gain=controls[i+3]->get();b.q=controls[i+4]->get();b.slope=6*juce::roundToInt(controls[82+n]->get()/6);}return e;}
void BuiltinEffect::setEqualizer(const Equalizer& e){if(!validEqualizer(e))return;auto set=[&](int i,float v){controls[i]->beginChangeGesture();controls[i]->setValueNotifyingHost(controls[i]->convertTo0to1(v));controls[i]->endChangeGesture();};set(0,e.enabled?1.f:0.f);set(1,(float)e.output);for(int n=0;n<16;++n){const auto& b=e.bands[n];int i=2+n*5;set(i,b.enabled?1.f:0.f);set(i+1,(float)b.type);set(i+2,(float)b.frequency);set(i+3,(float)b.gain);set(i+4,(float)b.q);set(82+n,(float)b.slope);}}
void BuiltinEffect::prepareToPlay(double rate,int frames){hz=rate;dryAudio.setSize(2,juce::jmax(frames,65536));dryLatency.prepare({rate,(juce::uint32)juce::jmax(1,frames),2});bypassBlend.reset(rate,.01);matchSmooth.reset(rate,.1);if((int)kind>=9)creative.prepare(kind,rate);if(kind==BuiltinKind::stereoWidth){widthDelay.setSize(2,(int)std::ceil(.03*rate)+4);monoBlend.reset(rate,.01);}if(spectrum)spectrum->rate.store(rate);if(waveform)waveform->rate.store(rate);oversampling.reset();if(kind==BuiltinKind::saturation || kind==BuiltinKind::clipper){oversampling=std::make_unique<juce::dsp::Oversampling<float>>(2,1,juce::dsp::Oversampling<float>::filterHalfBandPolyphaseIIR,true,true);oversampling->initProcessing((size_t)frames);setLatencySamples(juce::roundToInt(oversampling->getLatencyInSamples()));}else setLatencySamples(kind==BuiltinKind::frequencyShifter?31:0);for(size_t i=0;i<smooth.size();++i){smooth[i].reset(hz*(oversampling?2:1),.01);smooth[i].setCurrentAndTargetValue(controls[i]->get());}reset();}
void BuiltinEffect::reset(){creative.reset();dryLatency.reset();dryLatency.setDelay((float)getLatencySamples());bypassBlend.setCurrentAndTargetValue(auditionBypass.load()?1.f:0.f);matchSmooth.setCurrentAndTargetValue(1);dryEnergy=wetEnergy=0;detectorLowL=detectorLowR=tubeDcL=tubeDcR=0;dynamicGain.store(0);detectorLevel.store(0);if(kind==BuiltinKind::stereoWidth){widthDelay.clear();widthWrite=0;bassL=bassR=0;energyL=energyR=crossEnergy=0;correlation.store(1);monoChange.store(0);stereoActive.store(false);monoBlend.setCurrentAndTargetValue(monoCheck.load()?1.f:0.f);}envelope=fast=slow=0;gainEnvelope=kind==BuiltinKind::gate?0.f:1.f;gateOpen=false;inputPeak.store(0);outputPeak.store(0);reduction.store(0);if(oversampling)oversampling->reset();if(kind==BuiltinKind::eq)eq.reset(equalizer(),hz);}
void BuiltinEffect::processBlock(juce::AudioBuffer<float>& audio,juce::MidiBuffer&){
    juce::ScopedNoDenormals denormals;if(audio.getNumChannels()<2)return;
    double bpm=120;if(auto* playHead=getPlayHead())if(auto pos=playHead->getPosition())if(auto tempo=pos->getBpm())bpm=*tempo;
    if((int)kind>=9)creative.begin(kind,controls);
    const int dryFrames=juce::jmin(audio.getNumSamples(),dryAudio.getNumSamples());for(int c=0;c<2;++c)for(int n=0;n<dryFrames;++n){dryLatency.pushSample(c,audio.getSample(c,n));dryAudio.setSample(c,n,dryLatency.popSample(c));}
    if(kind==BuiltinKind::stereoWidth)monoBlend.setTargetValue(monoCheck.load()?1.f:0.f);
    const double widthMeter=1-std::exp(-1/(hz*.15));
    const float meterDecay=std::exp(-(float)audio.getNumSamples()/((float)hz*.5f));
    inputPeak.store(juce::jmax(juce::jmax(audio.getMagnitude(0,0,audio.getNumSamples()),audio.getMagnitude(1,0,audio.getNumSamples())),inputPeak.load()*meterDecay));float maxReduction=0;
    if(kind==BuiltinKind::eq){eq.update(equalizer(),hz);for(int n=0;n<audio.getNumSamples();++n){eq.process(audio.getWritePointer(0)[n],audio.getWritePointer(1)[n]);if(spectrum)spectrum->push(audio.getSample(0,n),audio.getSample(1,n));}}
    else {
        for(size_t i=0;i<controls.size();++i)smooth[i].setTargetValue(controls[i]->get());
        juce::dsp::AudioBlock<float> original(audio);auto block=oversampling?oversampling->processSamplesUp(original):original;
        auto* l=block.getChannelPointer(0);auto* r=block.getChannelPointer(1);
        auto db=[](float v){return juce::Decibels::decibelsToGain(v);};
        for(size_t n=0;n<block.getNumSamples();++n){std::array<float,16> p{};for(size_t i=0;i<controls.size();++i)p[i]=smooth[i].getNextValue();float a=l[n],b=r[n];if(!std::isfinite(a))a=0;if(!std::isfinite(b))b=0;float peak=juce::jmax(std::abs(a),std::abs(b));
            auto coefficient=[&](float ms){return std::exp(-1.f/(.001f*ms*(float)hz));};
            switch(kind){
            case BuiltinKind::compressor:{if(p[7]>0){const float hp=1-std::exp(-juce::MathConstants<float>::twoPi*p[7]/(float)hz);detectorLowL+=hp*(a-detectorLowL);detectorLowR+=hp*(b-detectorLowR);peak=juce::jmax(std::abs(a-detectorLowL),std::abs(b-detectorLowR));}float c=coefficient(peak>envelope?p[2]:p[3]);envelope=c*envelope+(1-c)*peak;float over=juce::Decibels::gainToDecibels(envelope,-120.f)-p[0];float knee=p[6];float amount=juce::jmax(0.f,over);if(knee>0 && over> -knee*.5f && over<knee*.5f)amount=(over+knee*.5f)*(over+knee*.5f)/(2*knee);float reductionDb=amount*(1-1/p[1]);float g=db(-reductionDb+p[4]);float mix=p[5]*.01f;g=1+mix*(g-1);a*=g;b*=g;maxReduction=juce::jmax(maxReduction,reductionDb);break;}
            case BuiltinKind::gate:{float detector=coefficient(peak>envelope?.1f:20.f);envelope=detector*envelope+(1-detector)*peak;if(gateOpen){if(envelope<db(p[0]-3))gateOpen=false;}else if(envelope>=db(p[0]))gateOpen=true;float target=gateOpen?1.f:db(-p[1]);float c=coefficient(target>gainEnvelope?p[2]:p[3]);gainEnvelope=c*gainEnvelope+(1-c)*target;a*=gainEnvelope;b*=gainEnvelope;maxReduction=juce::jmax(maxReduction,-juce::Decibels::gainToDecibels(gainEnvelope,-100.f));break;}
            case BuiltinKind::transient:{float f=coefficient(peak>fast?1.f:10.f),s=coefficient(p[2]);fast=f*fast+(1-f)*peak;slow=s*slow+(1-s)*peak;float onset=juce::jlimit(0.f,1.f,(fast-slow)/juce::jmax(.000001f,fast));float g=db(onset*p[0]+(1-onset)*p[1]+p[3]);a*=g;b*=g;break;}
            case BuiltinKind::saturation:{float drive=db(p[0]),mix=p[1]*.01f,out=db(p[2]);auto shape=[&](float x){switch(juce::roundToInt(controls[3]->get())){case 1:return (std::tanh((x+.2f)*drive)-std::tanh(.2f*drive))/juce::jmax(std::tanh(1.2f*drive)-std::tanh(.2f*drive),std::tanh(.2f*drive)-std::tanh(-.8f*drive));case 2:return juce::jlimit(-1.f,1.f,x*drive);default:return std::tanh(x*drive)/std::tanh(drive);}};a=(a+(shape(a)-a)*mix)*out;b=(b+(shape(b)-b)*mix)*out;if(controls[3]->get()>=.5f && controls[3]->get()<1.5f){const float dc=1-std::exp(-juce::MathConstants<float>::twoPi*10/(float)(hz*2));tubeDcL+=dc*(a-tubeDcL);tubeDcR+=dc*(b-tubeDcR);a-=tubeDcL*mix;b-=tubeDcR*mix;}break;}
            case BuiltinKind::clipper:{float drive=db(p[0]),ceiling=db(p[1]),soft=p[2]*.01f,out=db(p[3]);auto clip=[&](float v){v=v*drive/ceiling;return ((1-soft)*juce::jlimit(-1.f,1.f,v)+soft*std::tanh(v))*ceiling*out;};a=clip(a);b=clip(b);break;}
            case BuiltinKind::limiter:{float drive=db(p[0]),ceiling=db(p[1]);a*=drive;b*=drive;peak=juce::jmax(std::abs(a),std::abs(b));float target=peak>ceiling?ceiling/peak:1.f;float c=coefficient(p[2]);gainEnvelope=target<gainEnvelope?target:c*gainEnvelope+(1-c)*target;a=juce::jlimit(-ceiling,ceiling,a*gainEnvelope);b=juce::jlimit(-ceiling,ceiling,b*gainEnvelope);maxReduction=juce::jmax(maxReduction,-juce::Decibels::gainToDecibels(gainEnvelope,-100.f));break;}
            case BuiltinKind::stereoWidth:{
                const int length=widthDelay.getNumSamples();if(length<4)break;
                const float bassCoefficient=1-std::exp(-juce::MathConstants<float>::twoPi*p[3]/(float)hz);
                bassL+=bassCoefficient*(a-bassL);bassR+=bassCoefficient*(b-bassR);
                const float protect=p[2],lowL=bassL*protect,lowR=bassR*protect,monoBass=(lowL+lowR)*.5f;
                const float highL=a-lowL,highR=b-lowR;widthDelay.setSample(0,widthWrite,highL);widthDelay.setSample(1,widthWrite,highR);
                double position=widthWrite-p[0]*.001*hz;while(position<0)position+=length;const int first=(int)position,second=(first+1)%length;const float fraction=(float)(position-first);
                auto delayed=[&](int channel){return widthDelay.getSample(channel,first)+(widthDelay.getSample(channel,second)-widthDelay.getSample(channel,first))*fraction;};
                const float wetL=monoBass+highL+(delayed(0)-highL)*(1-p[1]),wetR=monoBass+highR+(delayed(1)-highR)*p[1];
                const float mix=p[5]*.01f;a+=(wetL-a)*mix;b+=(wetR-b)*mix;
                const float pan=p[4]*.01f;a*=pan>0?std::cos(pan*juce::MathConstants<float>::halfPi):1;b*=pan<0?std::cos(-pan*juce::MathConstants<float>::halfPi):1;
                const double meter=widthMeter;energyL+=meter*(a*a-energyL);energyR+=meter*(b*b-energyR);crossEnergy+=meter*(a*b-crossEnergy);
                const float mono=(a+b)*.5f,blend=monoBlend.getNextValue();if(blend>=1)a=b=mono;else{a+=(mono-a)*blend;b+=(mono-b)*blend;}widthWrite=(widthWrite+1)%length;break;}
            case BuiltinKind::utility:{switch(juce::roundToInt(controls[4]->get())){case 1:b=a;break;case 2:a=b;break;case 3:std::swap(a,b);break;}float mid=(a+b)*.5f,side=(a-b)*.5f*p[1]*.01f;a=(mid+side)*db(p[0])*(controls[2]->get()>=.5f?-1:1);b=(mid-side)*db(p[0])*(controls[3]->get()>=.5f?-1:1);a*=juce::jmin(1.f,1-p[5]*.01f);b*=juce::jmin(1.f,1+p[5]*.01f);break;}
            default:if((int)kind>=9){const float scL=audio.getNumChannels()>2?audio.getSample(2,(int)n):0,scR=audio.getNumChannels()>3?audio.getSample(3,(int)n):0;creative.process(kind,a,b,scL,scR,p,bpm);maxReduction=juce::jmax(maxReduction,creative.reduction);}break;}
            l[n]=std::isfinite(a)?a:0;r[n]=std::isfinite(b)?b:0;
        }
        if(oversampling)oversampling->processSamplesDown(original);
        // Downsampling can overshoot a clipped waveform; honour the stated sample ceiling.
        if(kind==BuiltinKind::clipper){float ceiling=juce::Decibels::decibelsToGain(controls[1]->get()+controls[3]->get());for(int c=0;c<2;++c)for(int n=0;n<audio.getNumSamples();++n)audio.setSample(c,n,juce::jlimit(-ceiling,ceiling,audio.getSample(c,n)));}
    }
    if((int)kind>=9){dynamicGain.store(creative.reduction);detectorLevel.store(creative.detectorPeak);}
    bypassBlend.setTargetValue(auditionBypass.load()?1.f:0.f);const double energyCoefficient=1-std::exp(-1/(hz*.3));
    for(int n=0;n<dryFrames;++n){float l=audio.getSample(0,n),r=audio.getSample(1,n),dl=dryAudio.getSample(0,n),dr=dryAudio.getSample(1,n);dryEnergy+=energyCoefficient*((dl*dl+dr*dr)*.5-dryEnergy);wetEnergy+=energyCoefficient*((l*l+r*r)*.5-wetEnergy);if(levelMatch.load() && dryEnergy>1e-8 && wetEnergy>1e-8)matchSmooth.setTargetValue((float)std::clamp(std::sqrt(dryEnergy/wetEnergy),.25,4.0));else if(!levelMatch.load())matchSmooth.setTargetValue(1);const float matched=matchSmooth.getNextValue(),bypass=bypassBlend.getNextValue();audio.setSample(0,n,(l*matched)+(dl-l*matched)*bypass);audio.setSample(1,n,(r*matched)+(dr-r*matched)*bypass);}matchGain.store(matchSmooth.getCurrentValue());
    if(kind==BuiltinKind::stereoWidth){const double total=energyL+energyR;stereoActive.store(total>1e-9);correlation.store(total>1e-9?(float)std::clamp(crossEnergy/std::sqrt(std::max(1e-30,energyL*energyR)),-1.0,1.0):1.f);monoChange.store(total>1e-9?juce::Decibels::gainToDecibels((float)std::sqrt(std::clamp(.5+crossEnergy/total,0.0,1.0)),-60.f):0.f);}
    if(kind==BuiltinKind::dynamicEq && spectrum)for(int n=0;n<audio.getNumSamples();++n)spectrum->push(audio.getSample(0,n),audio.getSample(1,n));
    if(waveform && waveform->enabled.load(std::memory_order_relaxed))for(int n=0;n<audio.getNumSamples();++n)waveform->push(audio.getSample(0,n),audio.getSample(1,n));
    reduction.store(juce::jmax(maxReduction,reduction.load()*meterDecay));outputPeak.store(juce::jmax(juce::jmax(audio.getMagnitude(0,0,audio.getNumSamples()),audio.getMagnitude(1,0,audio.getNumSamples())),outputPeak.load()*meterDecay));
}
void BuiltinEffect::getStateInformation(juce::MemoryBlock& b){juce::XmlElement xml("DrumEffect");xml.setAttribute("version",4);xml.setAttribute("kind",(int)kind);for(size_t i=0;i<controls.size();++i)xml.setAttribute("p"+juce::String(i),(double)controls[i]->get());copyXmlToBinary(xml,b);}
void BuiltinEffect::setStateInformation(const void* data,int size){auto xml=getXmlFromBinary(data,size);monoCheck.store(false);auditionBypass.store(false);levelMatch.store(false);if(!xml || !xml->hasTagName("DrumEffect") || xml->getIntAttribute("kind",-1)!=(int)kind)return;const int version=xml->getIntAttribute("version",1);const size_t count=kind==BuiltinKind::utility && version<4?5:kind==BuiltinKind::eq && version<2?42:version<3 && kind==BuiltinKind::compressor?7:version<3 && kind==BuiltinKind::saturation?3:controls.size();for(size_t i=0;i<count;++i){auto key="p"+juce::String(i);if(!xml->hasAttribute(key))return;auto v=xml->getDoubleAttribute(key);if(!std::isfinite(v) || v<controls[i]->range.start || v>controls[i]->range.end)return;}for(size_t i=0;i<controls.size();++i)controls[i]->setValueNotifyingHost(i>=count?static_cast<juce::AudioProcessorParameter*>(controls[i])->getDefaultValue():controls[i]->convertTo0to1((float)xml->getDoubleAttribute("p"+juce::String(i))));}
void BuiltinEffect::resetParameters(){monoCheck.store(false);auditionBypass.store(false);levelMatch.store(false);for(auto* p:controls){p->beginChangeGesture();p->setValueNotifyingHost(static_cast<juce::AudioProcessorParameter*>(p)->getDefaultValue());p->endChangeGesture();}}

double BuiltinEffect::getTailLengthSeconds() const {if(kind==BuiltinKind::tempoDelay || kind==BuiltinKind::echo){if(controls[7]->get()<=0)return 0;const double delay=controls[1]->get()>=.5?12:controls[0]->get()*.001,feedback=controls[3]->get()*.01;return std::min(600.0,delay*(feedback>.001?std::ceil(std::log(.001)/std::log(feedback))+1:1));}if(kind==BuiltinKind::room)return controls[4]->get()>0?20:0;if(kind==BuiltinKind::resonator)return controls[4]->get()>0?controls[1]->get()*.001:0;if(kind==BuiltinKind::frequencyShifter)return 31/hz;if(kind==BuiltinKind::stereoWidth)return .03;return 0;}
void BuiltinEffect::swapComparison(){auto& current=comparisons[comparisonB?1:0];current.clear();for(auto* p:controls)current.push_back(p->get());auto& other=comparisons[comparisonB?0:1];if(other.empty())other=current;comparisonB=!comparisonB;for(size_t i=0;i<controls.size();++i)controls[i]->setValueNotifyingHost(controls[i]->convertTo0to1(other[i]));}

class BuiltinLook final : public ValueBarLook {public: void drawRotarySlider(juce::Graphics& g,int x,int y,int w,int h,float v,float a,float b,juce::Slider& s) override{drawDrumRotary(g,x,y,w,h,v,a,b,s);}};
class BuiltinEditor final : public juce::AudioProcessorEditor,private juce::Timer {
    BuiltinLook look;BuiltinEffect& effect;BuiltinGraph graph;EqualizerEditor eqEditor;std::vector<int> order;juce::ToggleButton matchButton{"Level match"},compareBypass{"Bypass"};juce::TextButton compareButton{"A/B: A"};juce::ToggleButton monoButton{"Mono check"};juce::TextButton resetButton{"Reset"};juce::Label meters;std::vector<std::unique_ptr<juce::Slider>> knobs;std::vector<std::unique_ptr<juce::Label>> labels;std::vector<std::unique_ptr<juce::ToggleButton>> ticks;std::vector<std::unique_ptr<juce::ComboBox>> selectors;
public:
    explicit BuiltinEditor(BuiltinEffect& p):AudioProcessorEditor(p),effect(p),graph(p){setLookAndFeel(&look);addAndMakeVisible(matchButton);addAndMakeVisible(compareBypass);addAndMakeVisible(compareButton);matchButton.setComponentID("effect-level-match");compareBypass.setComponentID("effect-audition-bypass");compareButton.setComponentID("effect-ab");matchButton.setTooltip("Match processed RMS to the input while comparing, capped at +/-12 dB. Temporary listening tool; not saved.");compareBypass.setTooltip("Crossfade to latency-aligned dry audio. Enable Level match to compare at similar loudness. Temporary; not saved.");compareButton.setTooltip("Switch between two parameter snapshots. First switch copies A to B; edit B, then switch back to compare.");matchButton.onClick=[this]{effect.levelMatch.store(matchButton.getToggleState());};compareBypass.onClick=[this]{effect.auditionBypass.store(compareBypass.getToggleState());};compareButton.onClick=[this]{effect.swapComparison();refresh();};if(p.kind==BuiltinKind::stereoWidth){addAndMakeVisible(monoButton);monoButton.setComponentID("width-mono-check");monoButton.setTooltip("Audition this effect output in mono. Temporary: not saved; switches off when the editor closes. Affects this instrument, not the whole mix.");monoButton.onClick=[this]{effect.monoCheck.store(monoButton.getToggleState());};}addAndMakeVisible(resetButton);resetButton.onClick=[this]{effect.resetParameters();refresh();};addAndMakeVisible(meters);meters.setColour(juce::Label::textColourId,juce::Colours::white);
        if(p.kind==BuiltinKind::eq){addAndMakeVisible(eqEditor);eqEditor.update(p.equalizer(),p.getSampleRate());eqEditor.setSpectrum(p.spectrum.get());eqEditor.onChange=[this](const Equalizer& e){effect.setEqualizer(e);};setSize(1100,690);}else{addAndMakeVisible(graph);for(int n=0;n<(int)p.controls.size();++n)if(p.controls[(size_t)n]->getName(40)!="Mix")order.push_back(n);for(int n=0;n<(int)p.controls.size();++n)if(p.controls[(size_t)n]->getName(40)=="Mix")order.push_back(n);for(int n:order){auto* parameter=p.controls[(size_t)n];auto slider=std::make_unique<ResetSlider>();slider->setComponentID("builtin-knob-"+parameter->getName(40));configureDjlRotary(*slider,parameter->range.start<0 && parameter->range.end>0 && std::abs(parameter->range.start+parameter->range.end)<.001f);slider->setRange(parameter->range.start,parameter->range.end,p.kind==BuiltinKind::stereoWidth && (n==1 || n==2)?1:.01);if(p.kind==BuiltinKind::stereoWidth && (n==1 || n==2)){slider->valueFromTextFunction=[n](const juce::String& text){return n==1?(text.containsIgnoreCase("Right")?1.0:0.0):(text.containsIgnoreCase("On")?1.0:0.0);};slider->textFromValueFunction=[n](double v){return n==1?(v<.5?juce::String("Left"):juce::String("Right")):(v<.5?juce::String("Off"):juce::String("On"));};}if((p.kind==BuiltinKind::stereoWidth && n==4) || (p.kind==BuiltinKind::utility && n==5)){if(p.kind==BuiltinKind::utility)slider->setRange(-100,100,1);slider->valueFromTextFunction=[](const juce::String& text){return text.trim().equalsIgnoreCase("C")?0.0:text.containsIgnoreCase("L")?-std::abs(text.getDoubleValue()):text.containsIgnoreCase("R")?std::abs(text.getDoubleValue()):text.getDoubleValue();};slider->textFromValueFunction=[](double v){return std::abs(v)<.5?juce::String("C"):juce::String(std::abs(v),0)+(v<0?" L":" R");};}juce::StringArray choices;if(p.kind==BuiltinKind::saturation && n==3)choices={"Soft","Tube","Hard"};if((p.kind==BuiltinKind::tempoDelay || p.kind==BuiltinKind::echo) && (n==1 || n==6))choices={"Off","On"};if((p.kind==BuiltinKind::tempoDelay || p.kind==BuiltinKind::echo) && n==2)choices={"1/64","1/32","1/16","1/8","Dotted 1/8","1/4","Dotted 1/4","1/2","1 bar"};if(!choices.isEmpty()){slider->setRange(parameter->range.start,parameter->range.end,1);slider->textFromValueFunction=[choices](double v){return choices[juce::jlimit(0,choices.size()-1,(int)std::round(v))];};slider->valueFromTextFunction=[choices](const juce::String& t){for(int i=0;i<choices.size();++i)if(t.trim().equalsIgnoreCase(choices[i]))return (double)i;return t.getDoubleValue();};}if(p.kind==BuiltinKind::bitcrusher && n==0)slider->setRange(2,24,1);
slider->setTextValueSuffix(" "+parameter->getLabel());slider->setDoubleClickReturnValue(true,parameter->convertFrom0to1(static_cast<juce::AudioProcessorParameter*>(parameter)->getDefaultValue()));slider->setValue(parameter->get(),juce::dontSendNotification);slider->onDragStart=[parameter]{parameter->beginChangeGesture();};slider->onDragEnd=[parameter]{parameter->endChangeGesture();};slider->onValueChange=[parameter,s=slider.get()]{parameter->setValueNotifyingHost(parameter->convertTo0to1((float)s->getValue()));};addAndMakeVisible(*slider);knobs.push_back(std::move(slider));auto label=std::make_unique<juce::Label>();label->setText(parameter->getName(40),juce::dontSendNotification);label->setColour(juce::Label::textColourId,juce::Colours::white);label->setJustificationType(juce::Justification::centred);label->setFont(juce::FontOptions(14));addAndMakeVisible(*label);labels.push_back(std::move(label));
const auto title=parameter->getName(40);auto* value=knobs.back().get();const bool binary=title=="Invert L" || title=="Invert R" || title=="Protect bass" || title=="Sync" || title=="Ping pong";
std::unique_ptr<juce::ToggleButton> tick;std::unique_ptr<juce::ComboBox> selector;
if(binary){tick=std::make_unique<juce::ToggleButton>(title);tick->setComponentID("builtin-toggle-"+title);tick->onClick=[value,button=tick.get()]{juce::Slider::ScopedDragNotification gesture(*value);value->setValue(button->getToggleState()?1:0,juce::sendNotificationSync);};addAndMakeVisible(*tick);value->setVisible(false);labels.back()->setVisible(false);}
else {juce::StringArray options;if(title=="Character")options={"Soft","Tube","Hard"};if(title=="Channels")options={"Stereo","Left only","Right only","Swap L/R"};if(title=="Delayed side")options={"Left","Right"};if(title=="Division")options={"1/64","1/32","1/16","1/8","Dotted 1/8","1/4","Dotted 1/4","1/2","1 bar"};if(!options.isEmpty()){selector=std::make_unique<juce::ComboBox>();selector->setComponentID("builtin-choice-"+title);selector->addItemList(options,1);selector->onChange=[value,box=selector.get()]{juce::Slider::ScopedDragNotification gesture(*value);value->setValue(box->getSelectedId()-1,juce::sendNotificationSync);};addAndMakeVisible(*selector);value->setVisible(false);}}
ticks.push_back(std::move(tick));selectors.push_back(std::move(selector));
}const int width=juce::jmax(654,juce::jmin(1000,(int)knobs.size()*112+24)),columns=juce::jmax(1,(width-24)/112);setSize(width,300+112*((int(knobs.size())+columns-1)/columns));}timerCallback();startTimerHz(15);}
    ~BuiltinEditor() override{effect.monoCheck.store(false);effect.auditionBypass.store(false);effect.levelMatch.store(false);stopTimer();setLookAndFeel(nullptr);}
    void paint(juce::Graphics& g) override{g.fillAll(juce::Colour(0xff19212e));}
    void resized() override{resetButton.setBounds(getWidth()-90,8,80,25);monoButton.setBounds(getWidth()-216,8,120,25);matchButton.setBounds(12,8,112,25);compareBypass.setBounds(132,8,88,25);compareButton.setBounds(228,8,80,25);meters.setBounds(12,38,getWidth()-24,24);if(effect.kind==BuiltinKind::eq)eqEditor.setBounds(8,68,getWidth()-16,getHeight()-76);else {graph.setBounds(12,68,getWidth()-24,208);const int columns=juce::jmax(1,(getWidth()-24)/112),rows=juce::jmax(1,((int)knobs.size()+columns-1)/columns),w=(getWidth()-24)/columns,rowHeight=juce::jmax(1,(getHeight()-288)/rows);for(size_t i=0;i<knobs.size();++i){int x=12+((labels[i]->getText()=="Mix")?columns-1:(int)i%columns)*w,y=288+((int)i/columns)*rowHeight;labels[i]->setBounds(x,y,w,20);knobs[i]->setBounds(x+(w-100)/2,y+20,100,juce::jmax(1,rowHeight-22));if(ticks[i])ticks[i]->setBounds(x+4,y+35,w-8,30);if(selectors[i])selectors[i]->setBounds(x+4,y+38,w-8,30);}}}
    void refresh(){matchButton.setToggleState(effect.levelMatch.load(),juce::dontSendNotification);compareBypass.setToggleState(effect.auditionBypass.load(),juce::dontSendNotification);compareButton.setButtonText(effect.comparisonB?"A/B: B":"A/B: A");monoButton.setToggleState(effect.monoCheck.load(),juce::dontSendNotification);if(effect.kind==BuiltinKind::eq)eqEditor.update(effect.equalizer(),effect.getSampleRate());else for(size_t i=0;i<knobs.size();++i){if(!knobs[i]->isMouseButtonDown() && !knobs[i]->hasKeyboardFocus(true))knobs[i]->setValue(effect.controls[(size_t)order[i]]->get(),juce::dontSendNotification);if(ticks[i])ticks[i]->setToggleState(knobs[i]->getValue()>=.5,juce::dontSendNotification);if(selectors[i])selectors[i]->setSelectedId((int)std::round(knobs[i]->getValue())+1,juce::dontSendNotification);const auto title=effect.controls[(size_t)order[i]]->getName(40);bool available=true;if(effect.kind==BuiltinKind::tempoDelay || effect.kind==BuiltinKind::echo){if(title=="Time")available=effect.controls[1]->get()<.5f;if(title=="Division")available=effect.controls[1]->get()>=.5f;}if(effect.kind==BuiltinKind::echo && title=="Wow rate")available=effect.controls[9]->get()>0;if(effect.kind==BuiltinKind::stereoWidth && title=="Bass below")available=effect.controls[2]->get()>=.5f;knobs[i]->setEnabled(available);if(selectors[i])selectors[i]->setEnabled(available);labels[i]->setAlpha(available?1.f:.35f);}}
    void timerCallback() override{meters.setText("In "+juce::String(juce::Decibels::gainToDecibels(effect.inputPeak.load(),-100.f),1)+" dBFS   Out "+juce::String(juce::Decibels::gainToDecibels(effect.outputPeak.load(),-100.f),1)+" dBFS   Reduction "+juce::String(effect.reduction.load(),1)+" dB",juce::dontSendNotification);refresh();graph.tick();}
};
juce::AudioProcessorEditor* BuiltinEffect::createEditor(){return new BuiltinEditor(*this);}

std::vector<EffectSlot> factoryChain(int preset){std::vector<EffectSlot> result;auto add=[&](BuiltinKind kind,bool bypassed){auto d=builtinDescription(kind);result.push_back({juce::Uuid().toString(),d.createXml()->toString(),{},bypassed});return result.size()-1;};if(preset==1 || preset==2){auto n=add(BuiltinKind::transient,false);BuiltinEffect effect(BuiltinKind::transient);effect.controls[0]->setValueNotifyingHost(effect.controls[0]->convertTo0to1(preset==1?4.f:6.f));effect.controls[1]->setValueNotifyingHost(effect.controls[1]->convertTo0to1(-3.f));juce::MemoryBlock state;effect.getStateInformation(state);result[n].state=state.toBase64Encoding();add(BuiltinKind::saturation,preset==2);add(BuiltinKind::limiter,false);}return result;}
juce::File defaultChainFile(){return juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory).getChildFile("DJL/Drum/default-chain.xml");}
bool saveChain(const juce::File& file,const std::vector<EffectSlot>& slots){if(slots.size()>maxEffects)return false;juce::XmlElement xml("DrumChain");xml.setAttribute("version",1);for(const auto& slot:slots){auto desc=juce::parseXML(slot.description);if(!desc)return false;auto* e=xml.createNewChildElement("Effect");e->setAttribute("bypassed",slot.bypassed);e->setAttribute("sidechainGain",slot.sidechainGain);e->setAttribute("sidechainMix",slot.sidechainMix);e->addChildElement(desc.release());e->createNewChildElement("State")->addTextElement(slot.state);}if(!file.getParentDirectory().createDirectory())return false;return file.replaceWithText(xml.toString());}
std::optional<std::vector<EffectSlot>> loadChain(const juce::File& file){if(!file.existsAsFile() || file.getSize()>24*1024*1024)return {};auto xml=juce::parseXML(file);if(!xml || !xml->hasTagName("DrumChain") || xml->getIntAttribute("version")!=1)return {};std::vector<EffectSlot> slots;for(auto* e:xml->getChildIterator()){auto* desc=e->getChildByName("PLUGIN");auto* state=e->getChildByName("State");if(!desc || !state || slots.size()>=maxEffects)return {};juce::PluginDescription d;if(!d.loadFromXml(*desc) || (!isBuiltin(d) && (d.pluginFormatName!="VST3" || d.isInstrument || !juce::File::isAbsolutePath(d.fileOrIdentifier))))return {};auto encoded=state->getAllSubText();juce::MemoryBlock block;if(encoded.isNotEmpty() && !block.fromBase64Encoding(encoded))return {};EffectSlot slot{juce::Uuid().toString(),desc->toString(),encoded,e->getBoolAttribute("bypassed")};slot.sidechainGain=e->getDoubleAttribute("sidechainGain",0);slot.sidechainMix=e->getDoubleAttribute("sidechainMix",1);if(!std::isfinite(slot.sidechainGain) || slot.sidechainGain< -60 || slot.sidechainGain>24 || !std::isfinite(slot.sidechainMix) || slot.sidechainMix<0 || slot.sidechainMix>1)return {};slots.push_back(slot);}return slots;}
std::vector<EffectSlot> defaultChain(){if(auto saved=loadChain(defaultChainFile()))return *saved;return factoryChain();}
}
